#include <unordered_set>
#include <vector>

using namespace std;


class Solution {
public:
    int numComponents(ListNode* head, vector<int>& nums) {
        unordered_set<int> s(nums.begin(), nums.end());
        int res = 0;
        while (head) {
            if (s.count(head->val) && (!head->next || !s.count(head->next->val)))
                res++;
            head = head->next;
        }
        return res;
    }
};
